class Solution {
  public int findClosest(String[] words, String word1, String word2) {
    int best = words.length, p1 = -1, p2 = -1;
    for (int i = 0; i < words.length; i++) {
      if (words[i].equals(word1)) {
        p1 = i;
        if (p2 != -1) best = Math.min(best, i - p2);
      } else if (words[i].equals(word2)) {
        p2 = i;
        if (p1 != -1) best = Math.min(best, i - p1);
      }
    }
    return best;
  }
}

class Solution:
    def findClosest(self, words: List[str], word1: str, word2: str) -> int:
        best = len(words)
        p1 = p2 = -1
        for i, w in enumerate(words):
            if w == word1:
                p1 = i
                if p2 != -1:
                    best = min(best, i - p2)
            elif w == word2:
                p2 = i
                if p1 != -1:
                    best = min(best, i - p1)
        return best

impl Solution {
  pub fn find_closest(words: Vec<String>, word1: String, word2: String) -> i32 {
    let mut best = words.len() as i32;
    let (mut p1, mut p2) = (-1i32, -1i32);
    for (i, w) in words.iter().enumerate() {
      if *w == word1 {
        p1 = i as i32;
        if p2 != -1 {
          best = best.min(i as i32 - p2);
        }
      } else if *w == word2 {
        p2 = i as i32;
        if p1 != -1 {
          best = best.min(i as i32 - p1);
        }
      }
    }
    best
  }
}

const findClosest = (words: string[], word1: string, word2: string): number => {
  let best = words.length;
  let p1 = -1;
  let p2 = -1;
  for (let i = 0; i < words.length; i++) {
    if (words[i] === word1) {
      p1 = i;
      if (p2 !== -1) best = Math.min(best, i - p2);
    } else if (words[i] === word2) {
      p2 = i;
      if (p1 !== -1) best = Math.min(best, i - p1);
    }
  }
  return best;
};
